import { defineSurteApp } from '@surte/shell-runtime/config';
import authModule from '@surte/module-auth';
import productsModule from '@surte/module-products';
import suppliersModule from '@surte/module-suppliers';
import stockModule from '@surte/module-stock';
import expirationModule from '@surte/module-expiration';
import purchasesModule from '@surte/module-purchases';
import salesModule from '@surte/module-sales';
import reportsModule from '@surte/module-reports';

export default defineSurteApp({
  name: 'Surte Wholesale',
  theme: 'warm-earth',
  locale: 'es-PE',
  infrastructure: { storage: 'local' },

  modules: [
    authModule({ providers: ['email', 'google'], requireAuth: true }),
    productsModule({ variant: 'full', enableBulkImport: true, enableImages: true }),
    suppliersModule({ enableMultiContact: true }),
    stockModule({ multiWarehouse: true, requireApproval: true }),
    expirationModule({ alertDaysBefore: [30, 15, 7] }),
    purchasesModule({ enableOrderTracking: true }),
    salesModule({ taxRules: 'PE', enablePOS: true, enableInvoicing: true }),
    reportsModule({ reports: ['kardex', 'sales', 'inventory-value'] }),
  ],

  layout: {
    shell: 'sidebar-topbar',
    sidebar: { collapsible: true },
  },
});

import { SurteProvider } from '@surte/shell-runtime';
import surteConfig from '../surte.config';

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="es-PE">
      <body>
        <SurteProvider config={surteConfig}>
          {children}
        </SurteProvider>
      </body>
    </html>
  );
}

import { StepRouter } from '@surte/shell-runtime';

export default function CatchAll() {
  return <StepRouter />;
}

import type { Product, Supplier, StockMovement } from '@surte/domain';

export const mockProducts: Product[] = [
  { id: 'p-001', sku: 'ARR-COS-50', name: 'Arroz Costeño 50kg', category: 'granos', cost: 22.00, price: 28.00, stock: 147, unit: 'saco' },
  { id: 'p-002', sku: 'ACE-PRI-1L', name: 'Aceite Primor 1L', category: 'aceites', cost: 6.50, price: 8.50, stock: 89, unit: 'botella' },
  // ... 50 productos más
];

export const mockSuppliers: Supplier[] = [
  { id: 's-001', name: 'Distribuidora Costeño', contact: '999-111-222', terms: 'net-30' },
  // ...
];

// Cargado en SurteProvider si localStorage vacío

import { defineSurteApp } from '@surte/shell-runtime/config';
import authModule from '@surte/module-auth';
import productsModule from '@surte/module-products';
import stockModule from '@surte/module-stock';

export default defineSurteApp({
  name: 'Bodega Simple',
  theme: 'warm-earth',
  locale: 'es-PE',
  infrastructure: { storage: 'local' },

  modules: [
    authModule({ providers: ['email'], requireAuth: true }),
    productsModule({ variant: 'minimal' }),
    stockModule({ multiWarehouse: false }),
  ],

  layout: {
    shell: 'topbar-only',  // ⭐ sin sidebar
  },
});

// EXACTAMENTE EL MISMO ARCHIVO QUE wholesale
import { StepRouter } from '@surte/shell-runtime';
export default function CatchAll() { return <StepRouter />; }

module.file:
import { z } from 'zod';
import type { ModuleManifest } from '@surte/core';
import { TOKENS } from '@surte/core';
import { ProductRepositoryLocalStorage } from '@surte/infrastructure';
import { productSteps } from './steps';
import { ProductsSidebarItem } from './sections/SidebarItem';
import { ProductsDashboardWidget } from './sections/DashboardWidget';

const configSchema = z.object({
  variant: z.enum(['full', 'minimal']).default('full'),
  enableBulkImport: z.boolean().default(true),
  enableImages: z.boolean().default(true),
});

export type ProductsConfig = z.infer<typeof configSchema>;

export const productsManifest: ModuleManifest<ProductsConfig> = {
  id: 'products',
  version: '1.0.0',
  displayName: 'Productos',

  steps: productSteps,

  slots: [
    { slot: 'sidebar.nav', id: 'products-nav', item: { label: 'Productos', icon: 'package', path: '/productos', order: 10 } },
    { slot: 'dashboard.widgets', id: 'products-kpi', component: ProductsDashboardWidget, priority: 1 },
  ],

  bindings: [
    { token: TOKENS.ProductRepository, factory: () => new ProductRepositoryLocalStorage() },
  ],

  lifecycle: {
    migrations: [
      { fromVersion: 0, toVersion: 1, run: (data) => data },
    ],
  },

  requires: ['storage'],
  configSchema,
};

import { lazy } from 'react';
import { z } from 'zod';
import type { Step } from '@surte/core';

// ⭐ TODOS los componentes son lazy (D4)
const ProductListView    = lazy(() => import('../views/ProductListView'));
const ProductDetailView  = lazy(() => import('../views/ProductDetailView'));
const CreateProductFlow  = lazy(() => import('../patterns/CreateProductFlow'));
const EditProductFlow    = lazy(() => import('../patterns/EditProductFlow'));
const BulkImportFlow     = lazy(() => import('../patterns/BulkImportFlow'));

const ProductListActions = lazy(() => import('../sections/ProductListActions'));
const ProductListFilters = lazy(() => import('../sections/ProductListFilters'));
const ProductDetailTabs  = lazy(() => import('../sections/ProductDetailTabs'));
const ProductDetailSidebar = lazy(() => import('../sections/ProductDetailSidebar'));
const ProductCreateHeader = lazy(() => import('../headers/ProductCreateHeader'));
const ImportProgressFooter = lazy(() => import('../footers/ImportProgressFooter'));

export const productSteps: Step[] = [
  // ─── LIST ───
  {
    id: 'products.list',
    moduleId: 'products',
    path: '/productos',
    render: {
      shell: 'inherit',
      slots: {
        main: ProductListView,
        'main.actions': ProductListActions,
        'main.filters': ProductListFilters,
      },
    },
    title: 'Productos',
    guards: [],
    transitions: { next: { type: 'push', stepId: 'products.create' } },
    contracts: {
      config: { schema: z.object({}), defaults: {}, description: 'Lista de productos' },
      slots: { injectable: [] },
      events: { emits: [{ name: 'productSelected', version: 1, payloadSchema: z.object({ productId: z.string() }), description: 'Producto seleccionado' }] },
    },
  },

  // ─── CREATE ───
  {
    id: 'products.create',
    moduleId: 'products',
    path: '/productos/nuevo',
    render: {
      shell: 'inherit',
      slots: {
        main: CreateProductFlow,
        header: ProductCreateHeader,  // ⭐ header custom con progress
      },
    },
    title: 'Nuevo Producto',
    breadcrumbs: [{ label: 'Productos', stepId: 'products.list' }, { label: 'Nuevo' }],
    guards: [],
    transitions: {
      next:   { type: 'replace', stepId: 'products.detail' },
      cancel: { type: 'replace', stepId: 'products.list' },
    },
    contracts: {
      config: {
        schema: z.object({
          variant: z.enum(['full', 'minimal']).default('full'),
          showSupplierStep: z.boolean().default(true),
        }),
        defaults: { variant: 'full', showSupplierStep: true },
        description: 'Wizard de creación de producto',
      },
      slots: {
        injectable: [
          { slotName: 'main.actions', description: 'Acciones extra en header', required: false, maxItems: 3 },
        ],
      },
      events: {
        emits: [
          { name: 'productCreated', version: 1, payloadSchema: z.object({ productId: z.string() }), description: 'Producto creado' },
        ],
      },
    },
  },

  // ─── DETAIL ───
  {
    id: 'products.detail',
    moduleId: 'products',
    path: '/productos/:id',
    render: {
      shell: 'inherit',
      slots: {
        main: ProductDetailView,
        'main.tabs': ProductDetailTabs,
        'right-panel': ProductDetailSidebar,  // ⭐ panel derecho
      },
    },
    title: ({ params }) => `Producto ${params.id}`,
    breadcrumbs: ({ params }) => [{ label: 'Productos', stepId: 'products.list' }, { label: params.id }],
    guards: [],
    transitions: {},
    contracts: {
      config: { schema: z.object({}), defaults: {}, description: 'Detalle de producto' },
      slots: { injectable: [] },
      events: { emits: [] },
    },
  },

  // ─── IMPORT (FULLSCREEN) ───
  {
    id: 'products.import',
    moduleId: 'products',
    path: '/productos/importar',
    render: {
      shell: 'fullscreen',  // ⭐ override del shell de la app
      slots: {
        main: BulkImportFlow,
        footer: ImportProgressFooter,
      },
    },
    title: 'Importar Productos',
    guards: [],
    transitions: {
      next:   { type: 'replace', stepId: 'products.list' },
      cancel: { type: 'replace', stepId: 'products.list' },
    },
    contracts: {
      config: { schema: z.object({}), defaults: {}, description: 'Importación masiva' },
      slots: { injectable: [] },
      events: { emits: [{ name: 'productsImported', version: 1, payloadSchema: z.object({ count: z.number() }), description: 'Importación completada' }] },
    },
  },
];
